syntax:
Consider a simple class template:

```c++
template <typename T>
class MyClass {
public:
  T data;
  MyClass(T val) : data(val) {}
};
```
Instantiation happens only when `MyClass` is used with a specific type, e.g., `MyClass<int> myInt(10);`  The compiler then generates code for `MyClass<int>`.  Failure to instantiate correctly can lead to linker errors if the compiled object file referencing the template lacks the necessary instantiation.

code_example:
#include <iostream>
#include <vector>
template <typename T>
class TemplateClass {
public:
  std::vector<T> data;
  TemplateClass(std::initializer_list<T> list) : data(list) {}
  void print() {
    for (const auto& item : data) {
      std::cout << item << " ";
    }
    std::cout << std::endl;
  }
};
int main() {
  TemplateClass<int> int_instance = {1, 2, 3};
  int_instance.print();
  TemplateClass<std::string> string_instance = {"hello", "world"};
  string_instance.print();
  //TemplateClass<double> double_instance; //Compiler might still instantiate this, despite lack of use, depending on optimization settings.
  return 0;
}
